-- Generated by unscoredTaskBackfillSql() in src/lib/cv/unscored-backfill.ts;
-- a test keeps this copy equal to it. Do not edit by hand.
--
-- Opens one candidate_review task for every match that has no current score,
-- is parked in an unscored state, is not a test record, is on a role that is
-- not filled, closed or archived, and has no open candidate_review task from
-- any source. The wording is the pipeline's own (candidateReviewTask).
--
-- Idempotent: a second run inserts nothing. It only inserts tasks: no score,
-- eligibility, admin_status, client_visibility or stage changes, and a task
-- row sends nothing to anyone. RETURNING lists what was opened.
--
-- Preview first by running the SELECT inside "unscored" on its own.
WITH unscored AS (
  SELECT m.id, m.organization_id, m.position_id, m.candidate_profile_id,
    m.processing_state::text AS final_state,
    coalesce(nullif(btrim(split_part(coalesce(m.processing_error_code, m.processing_state::text), ':', 1)), ''), 'unknown') AS code,
    coalesce(nullif(btrim(cp.full_name), ''), 'Candidate') AS who,
    coalesce(' for ' || nullif(btrim(p.title), ''), '') AS role,
    coalesce(' ' || nullif(btrim(m.processing_error_message), ''), '') AS detail
  FROM candidate_matches m
  LEFT JOIN candidate_profiles cp ON cp.id = m.candidate_profile_id
  LEFT JOIN positions p ON p.id = m.position_id
  WHERE m.current_score_run_id IS NULL
    AND m.processing_state::text IN ('failed', 'ocr_required', 'provider_blocked', 'manual_review_required')
    AND m.is_test_record = false
    AND coalesce(p.status::text, '') NOT IN ('filled', 'closed', 'archived')
    AND NOT EXISTS (
      SELECT 1 FROM tasks t
      WHERE t.candidate_match_id = m.id AND t.task_type = 'candidate_review'
        AND t.status IN ('open', 'in_progress') AND t.deleted_at IS NULL
    )
)
INSERT INTO tasks (organization_id, position_id, candidate_match_id, candidate_profile_id, task_type, title, description, priority, status, metadata)
SELECT u.organization_id, u.position_id, u.id, u.candidate_profile_id, 'candidate_review',
  CASE u.code
    WHEN 'cv_unreadable' THEN u.who || u.role || ': CV needs review before scoring'
    WHEN 'text_layer_missing' THEN u.who || u.role || ': CV needs review before scoring'
    WHEN 'storage_unreadable' THEN u.who || u.role || ': CV needs review before scoring'
    WHEN 'extract_empty' THEN u.who || u.role || ': CV needs review before scoring'
    WHEN 'encrypted_pdf' THEN u.who || u.role || ': CV needs review before scoring'
    WHEN 'legacy_doc_unsupported' THEN u.who || u.role || ': CV needs review before scoring'
    WHEN 'cv_text_thin' THEN u.who || u.role || ': CV needs review before scoring'
    WHEN 'missing_usable_cv' THEN u.who || u.role || ': not scored yet'
    WHEN 'position_inactive' THEN u.who || u.role || ': not scored yet'
    WHEN 'requirements_missing' THEN u.who || u.role || ': not scored yet'
    WHEN 'max_attempts_exceeded' THEN u.who || u.role || ': not scored yet'
    WHEN 'cv_employment_history_missing' THEN u.who || u.role || ': not scored yet'
    WHEN 'engine_error' THEN u.who || u.role || ': not scored yet'
    WHEN 'unknown' THEN u.who || u.role || ': not scored yet'
    ELSE u.who || u.role || ': not scored yet'
  END,
  CASE u.code
    WHEN 'cv_unreadable' THEN 'Read, but not readable. Text came out of the document, but it is not readable language — the encoding is damaged or the file is not really a text document.' || u.detail || ' Next: Run OCR on the document, or ask the candidate for a clean copy. If a new file is the fix, send the re-upload request from the parse-failure desk (/admin/parse-failures); nothing has been sent to the candidate.'
    WHEN 'text_layer_missing' THEN 'Scan without text. The document is a scan or an image, so it carries no text layer to read.' || u.detail || ' Next: Run OCR on the document, or ask the candidate for a text-based PDF. If a new file is the fix, send the re-upload request from the parse-failure desk (/admin/parse-failures); nothing has been sent to the candidate.'
    WHEN 'storage_unreadable' THEN 'Corrupt upload. The stored file could not be downloaded, so the upload is incomplete or corrupt.' || u.detail || ' Next: Ask the candidate to upload the document again; the stored copy is unusable. If a new file is the fix, send the re-upload request from the parse-failure desk (/admin/parse-failures); nothing has been sent to the candidate.'
    WHEN 'extract_empty' THEN 'Empty text layer. The file opened but produced no usable text.' || u.detail || ' Next: Ask the candidate to re-upload, or paste the CV text in by hand. If a new file is the fix, send the re-upload request from the parse-failure desk (/admin/parse-failures); nothing has been sent to the candidate.'
    WHEN 'encrypted_pdf' THEN 'Password protected. The PDF is password protected or otherwise restricted, so its text cannot be opened.' || u.detail || ' Next: Ask the candidate for an unprotected copy of the same document. If a new file is the fix, send the re-upload request from the parse-failure desk (/admin/parse-failures); nothing has been sent to the candidate.'
    WHEN 'legacy_doc_unsupported' THEN 'Old .doc format. The file is an old binary Word document, which is not a supported format.' || u.detail || ' Next: Ask the candidate for the same CV saved as a PDF. If a new file is the fix, send the re-upload request from the parse-failure desk (/admin/parse-failures); nothing has been sent to the candidate.'
    WHEN 'cv_text_thin' THEN 'Very little text. The file was read twice and still produced under 1,500 characters, too little to score fairly.' || u.detail || ' Next: Open the document: if the CV is genuinely short, score it by hand; if text is missing, ask for a re-upload. If a new file is the fix, send the re-upload request from the parse-failure desk (/admin/parse-failures); nothing has been sent to the candidate.'
    WHEN 'missing_usable_cv' THEN 'No CV is on file.' || u.detail || ' Next: Ask the candidate for a CV from the parse-failure desk, or attach one by hand.'
    WHEN 'position_inactive' THEN 'The role is not active, so the candidate was not scored.' || u.detail || ' Next: Activate the role to score them, or close the application.'
    WHEN 'requirements_missing' THEN 'The role has no structured requirements to score against.' || u.detail || ' Next: Add must-haves in the role editor; the candidate is rescored when they are saved.'
    WHEN 'max_attempts_exceeded' THEN 'Automatic processing failed repeatedly.' || u.detail || ' Next: Open the candidate, check the processing log, and retry once the cause is fixed.'
    WHEN 'cv_employment_history_missing' THEN 'No dated roles could be read from the CV.' || u.detail || ' Next: Open the CV. If its roles carry dates, rescore the candidate and report the layout the date check missed; if they do not, ask the candidate for the dates of each role. Nothing has been sent to the candidate.'
    WHEN 'engine_error' THEN 'The candidate could not be scored automatically.' || u.detail || ' Next: Open the candidate, check the processing log, and retry or score by hand.'
    WHEN 'unknown' THEN 'The candidate could not be scored automatically.' || u.detail || ' Next: Open the candidate, check the processing log, and retry or score by hand.'
    ELSE 'The candidate could not be scored automatically.' || u.detail || ' Next: Open the candidate, check the processing log, and retry or score by hand.'
  END,
  (CASE WHEN u.code IN ('engine_error', 'unknown') THEN 'high' ELSE 'normal' END)::task_priority,
  'open',
  jsonb_build_object('source', 'unscored_backfill', 'reason', u.code, 'final_state', u.final_state)
FROM unscored u
RETURNING id, candidate_match_id, title;
